//! The iPad app's static library. The Xcode wrapper project under `ios/` (generated by xcodegen from
//! `ios/project.yml`) links `libdc_ios_app.a` and its `main.m` calls [`dc_ios_main`], which runs the client's iOS
//! driver (`dc_client::ios_main`: one UIKit event loop for the front end and the matches, the keyboard and mouse
//! through dc-ios-hid). Off iOS the library is empty.

/// The app's entry: runs the client until the process ends (UIKit never returns from its event loop; the return
/// value is for a start that fails before the loop).
#[cfg(target_os = "ios")]
#[no_mangle]
pub extern "C" fn dc_ios_main() -> i32 {
    dc_client::ios_main()
}
